const request = $json.body ?? $json;
const payload = request.payload;
const idempotencyKey = $json.headers?.['idempotency-key'];
if (!request.delivery_id || idempotencyKey !== request.delivery_id) throw new Error('Delivery idempotency key mismatch');
const subjects = {
  status_update: `${payload.shopName}: repair status update`,
  completion_report: `${payload.shopName}: your repair is complete`,
  reminder: `${payload.shopName}: appointment reminder`,
  review_request: `${payload.shopName}: how did we do?`
};
if (!subjects[request.template_id]) throw new Error('Unsupported email template');
const escapeHtml = (value) => String(value ?? '').replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;').replaceAll("'", '&#039;');
const details = [
  `<strong>Vehicle:</strong> ${escapeHtml(payload.vehicle)}`,
  payload.status ? `<strong>Status:</strong> ${escapeHtml(payload.status)}` : null,
  payload.scheduledAt ? `<strong>Appointment:</strong> ${escapeHtml(payload.scheduledAt)}` : null
].filter(Boolean).join('<br>');
return [{json: {
  ...request,
  idempotency_key: idempotencyKey,
  callback_secret: $json.headers?.['x-autoshop-webhook-secret'],
  subject: subjects[request.template_id],
  html: `<div style="font-family:Arial,sans-serif;line-height:1.6;color:#18181b;max-width:560px"><p>Hi ${escapeHtml(payload.customerName)},</p><p>${escapeHtml(payload.messageBody)}</p><p>${details}</p><p style="color:#71717a;font-size:13px">${escapeHtml(payload.shopName)}<br>${escapeHtml(payload.shopAddress)}</p></div>`
}}];
